mod solution;

fn main() {
    let cases = [
    (r#"[7,2,3,0,5,10,3,12,18]"#, r#"0,0,3"#),
    (r#"[1,2,3,4,5,6,7]"#, r#"1,3,5"#),
    (r#"
[1,2,3,4,5,6,7]
"#, r#"1,3,5"#),
    (r#"  
[7,2,3,0,5,10,3,12,18]
  "#, r#"0,0,3"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS sparse-table");
}
